        Add("LibraryNoMatch", "No project matches your search.", "Geen project komt overeen met uw zoekopdracht.", "Kein Projekt entspricht Ihrer Suche.", "Aucun projet ne correspond à votre recherche.", "Ningún proyecto coincide con su búsqueda.");
        Add("NotesProjectChanged", "The project was replaced before these notes were saved, so they were not added to the new one.", "Het project is vervangen voordat deze notities waren bewaard, dus ze zijn niet aan het nieuwe project toegevoegd.", "Das Projekt wurde ersetzt, bevor diese Notizen gespeichert waren; sie wurden dem neuen Projekt nicht hinzugefügt.", "Le projet a été remplacé avant l’enregistrement de ces notes ; elles n’ont pas été ajoutées au nouveau.", "El proyecto se sustituyó antes de guardar estas notas, así que no se añadieron al nuevo.");
        Add("CloseUnsaved", "Your last change is still being saved. Close the window again to leave anyway.", "Uw laatste wijziging wordt nog bewaard. Sluit het venster opnieuw om toch af te sluiten.", "Ihre letzte Änderung wird noch gespeichert. Schließen Sie das Fenster erneut, um trotzdem zu beenden.", "Votre dernière modification est encore en cours d’enregistrement. Fermez à nouveau la fenêtre pour quitter malgré tout.", "Su último cambio aún se está guardando. Cierre la ventana de nuevo para salir de todos modos.");
        Add("LibraryEmptyTitle", "No saved projects yet", "Nog geen opgeslagen projecten", "Noch keine gespeicherten Projekte", "Aucun projet enregistré", "Aún no hay proyectos guardados");
        Add("ExportTitle", "Export", "Exporteren", "Exportieren", "Exporter", "Exportar");
        Add("PresetsHelp", "Start from a ready-made rhythm. Your current project is saved to the library first.", "Begin met een kant-en-klaar ritme. Uw huidige project wordt eerst in de bibliotheek bewaard.", "Mit einem fertigen Rhythmus beginnen. Ihr aktuelles Projekt wird zuvor in der Bibliothek gespeichert.", "Partez d’un rythme prêt à l’emploi. Votre projet actuel est d’abord enregistré dans la bibliothèque.", "Empiece con un ritmo listo para usar. Su proyecto actual se guarda antes en la biblioteca.");
        Add("PresetDesc_open", "A plain 4/4 at 120 BPM with a one-bar count-in. A good place to start.", "Een gewone 4/4 op 120 BPM met een maat aftellen. Een goed beginpunt.", "Ein einfacher 4/4-Takt bei 120 BPM mit einem Takt Einzählen. Ein guter Anfang.", "Un simple 4/4 à 120 BPM avec une mesure de décompte. Un bon point de départ.", "Un 4/4 sencillo a 120 BPM con un compás de entrada. Un buen punto de partida.");
        Add("PresetDesc_compound-6-8", "6/8 felt in two: the dotted quarter note is 80 BPM and each of the two main beats splits into three.", "6/8 in twee gevoeld: de gepuncteerde kwartnoot is 80 BPM en elk van de twee hoofdtellen valt in drieën uiteen.", "6/8 in Zwei gefühlt: Die punktierte Viertelnote ist 80 BPM, jeder der zwei Hauptschläge teilt sich in drei.", "6/8 ressenti à deux temps : la noire pointée vaut 80 BPM et chacun des deux temps principaux se divise en trois.", "6/8 sentido en dos: la negra con puntillo es 80 BPM y cada uno de los dos pulsos principales se divide en tres.");
        Add("PresetDesc_additive-7-8", "Seven eighth notes grouped 2+2+3. The first note of each group is stressed.", "Zeven achtste noten gegroepeerd als 2+2+3. De eerste noot van elke groep krijgt nadruk.", "Sieben Achtelnoten, gruppiert als 2+2+3. Die erste Note jeder Gruppe wird betont.", "Sept croches groupées en 2+2+3. La première note de chaque groupe est accentuée.", "Siete corcheas agrupadas como 2+2+3. La primera nota de cada grupo se acentúa.");
        Add("PresetDesc_swing", "Eighth notes with a swing feel: long-short pairs instead of even ones.", "Achtste noten met swing: lang-kort-paren in plaats van gelijke.", "Achtelnoten mit Swing-Gefühl: lang-kurz-Paare statt gleichmäßiger.", "Croches avec un feeling swing : des paires longue-brève plutôt que régulières.", "Corcheas con sensación de swing: pares largo-corto en lugar de iguales.");
        Add("PresetDesc_polyrhythm-3-4", "Three evenly spaced clicks against four beats in the same bar.", "Drie gelijkmatig verdeelde tikken tegen vier tellen in dezelfde maat.", "Drei gleichmäßig verteilte Klicks gegen vier Schläge im selben Takt.", "Trois clics régulièrement espacés contre quatre temps dans la même mesure.", "Tres clics a distancias iguales contra cuatro pulsos en el mismo compás.");
        Add("PresetDesc_polymeter-3-4", "A pulse in three and a pulse in four, running side by side. They meet again every 12 beats.", "Een puls in drie en een puls in vier, naast elkaar. Ze komen elke 12 tellen weer samen.", "Ein Puls in Drei und ein Puls in Vier, nebeneinander. Sie treffen sich alle 12 Zählzeiten wieder.", "Une pulsation à trois et une à quatre, côte à côte. Elles se retrouvent tous les 12 temps.", "Un pulso en tres y otro en cuatro, en paralelo. Vuelven a coincidir cada 12 pulsos.");
        Add("PresetDesc_euclidean-5-8", "Five clicks spread as evenly as possible over eight steps.", "Vijf tikken zo gelijk mogelijk verdeeld over acht stappen.", "Fünf Klicks, so gleichmäßig wie möglich auf acht Schritte verteilt.", "Cinq clics répartis aussi régulièrement que possible sur huit pas.", "Cinco clics repartidos lo más uniformemente posible en ocho pasos.");
        Add("PresetDesc_paradiddle", "Sixteen strokes of right-hand and left-hand sticking to practise on a pad.", "Zestien slagen rechter- en linkerhandsticking om op een pad te oefenen.", "Sechzehn Schläge Rechts-Links-Handsatz zum Üben auf dem Pad.", "Seize coups de doigté main droite et gauche à travailler sur un pad.", "Dieciséis golpes de digitación derecha e izquierda para practicar en un pad.");
        Add("PresetDesc_warmup-ladder", "Starts at 80 BPM and speeds up by 4 BPM every eight bars, up to 112.", "Begint op 80 BPM en gaat elke acht maten 4 BPM sneller, tot 112.", "Beginnt bei 80 BPM und wird alle acht Takte um 4 BPM schneller, bis 112.", "Commence à 80 BPM et accélère de 4 BPM toutes les huit mesures, jusqu’à 112.", "Empieza a 80 BPM y acelera 4 BPM cada ocho compases, hasta 112.");
        Add("PresetDesc_internal-time", "Two bars you hear, then two bars of silence, over and over. Keep the beat going yourself through the gaps.", "Twee maten hoorbaar, dan twee maten stilte, steeds opnieuw. Houd zelf de maat vast tijdens de stiltes.", "Zwei Takte hörbar, dann zwei Takte Stille, immer wieder. Halten Sie den Takt in den Lücken selbst.", "Deux mesures audibles, puis deux mesures de silence, en boucle. Gardez vous-même le tempo pendant les silences.", "Dos compases audibles y luego dos de silencio, una y otra vez. Mantenga usted mismo el pulso durante los silencios.");
        Add("PresetDesc_ramp-domains", "Speeds up from 60 to 120 BPM, slows back down to 60, then settles at 80. Two different ways of changing tempo, side by side.", "Versnelt van 60 naar 120 BPM, vertraagt terug naar 60 en komt dan uit op 80. Twee manieren om het tempo te veranderen, naast elkaar.", "Beschleunigt von 60 auf 120 BPM, wird wieder auf 60 langsamer und pendelt sich bei 80 ein. Zwei Arten der Tempoänderung im Vergleich.", "Accélère de 60 à 120 BPM, ralentit jusqu’à 60, puis se stabilise à 80. Deux façons de changer de tempo, côte à côte.", "Acelera de 60 a 120 BPM, vuelve a 60 y se asienta en 80. Dos formas de cambiar el tempo, una junto a otra.");
        Add("PresetDesc_seeded-density", "About half of the clicks are left out at random, so you have to keep the pulse yourself. The same pattern plays every time.", "Ongeveer de helft van de tikken valt willekeurig weg, dus u moet zelf de puls vasthouden. Elke keer klinkt hetzelfde patroon.", "Etwa die Hälfte der Klicks entfällt zufällig, Sie müssen den Puls also selbst halten. Jedes Mal erklingt dasselbe Muster.", "Environ la moitié des clics sont omis au hasard : à vous de garder la pulsation. Le même motif revient à chaque fois.", "Aproximadamente la mitad de los clics se omiten al azar, así que debe mantener usted el pulso. Suena el mismo patrón cada vez.");

        // Stage page (docs/design/pages-design.md).
        Add("StagePurpose", "A big, steady view for performing, with a setlist to move from song to song.", "Een grote, rustige weergave voor optreden, met een setlijst om van song naar song te gaan.", "Eine große, ruhige Ansicht für den Auftritt, mit einer Setliste von Song zu Song.", "Un affichage grand et stable pour jouer, avec une liste de scène pour passer d’un morceau à l’autre.", "Una vista grande y estable para actuar, con un repertorio para pasar de canción en canción.");
        Add("NowPlaying", "Now playing", "Nu aan het spelen", "Läuft gerade", "En cours", "Sonando ahora");
        Add("UpNextBadge", "Up next", "Hierna", "Als Nächstes", "Ensuite", "A continuación");
        Add("NothingUpNext", "Nothing selected: choose a song in the setlist.", "Niets geselecteerd: kies een song in de setlijst.", "Nichts ausgewählt: Wählen Sie einen Song in der Setliste.", "Rien de sélectionné : choisissez un morceau dans la liste.", "Nada seleccionado: elija una canción del repertorio.");
        Add("SetlistHelp", "The song you select plays next.", "De song die u selecteert, komt hierna.", "Der ausgewählte Song kommt als Nächstes.", "Le morceau sélectionné passe ensuite.", "La canción seleccionada suena a continuación.");
        Add("SetlistEmptyTitle", "No songs yet", "Nog geen songs", "Noch keine Songs", "Aucun morceau", "Aún no hay canciones");
        Add("NotesFor", "Notes for “{0}”", "Notities voor “{0}”", "Notizen zu „{0}“", "Notes pour « {0} »", "Notas de «{0}»");
        Add("NotesSaved", "Saved when you leave this box.", "Wordt bewaard zodra u het vak verlaat.", "Wird gespeichert, sobald Sie das Feld verlassen.", "Enregistré quand vous quittez ce champ.", "Se guarda al salir de este cuadro.");
        Add("LockHelp", "Stops accidental changes to the project while you perform. Playback is not affected.", "Voorkomt per ongeluk wijzigen van het project tijdens het optreden. Afspelen blijft werken.", "Verhindert versehentliche Änderungen am Projekt während des Auftritts. Die Wiedergabe bleibt möglich.", "Évite les modifications accidentelles du projet pendant la prestation. La lecture n’est pas affectée.", "Evita cambios accidentales en el proyecto durante la actuación. La reproducción no se ve afectada.");

        // Train page (docs/design/pages-design.md).
        Add("TrainPurpose", "Follow a practice program, and check how closely your key presses land on the clicks.", "Volg een oefenprogramma en controleer hoe dicht uw toetsdrukken bij de tikken liggen.", "Folgen Sie einem Übungsprogramm und prüfen Sie, wie genau Ihre Tastendrücke die Klicks treffen.", "Suivez un programme d’entraînement et vérifiez la précision de vos pressions sur les clics.", "Siga un programa de práctica y compruebe cuánto se acercan sus pulsaciones a los clics.");
        Add("TrainProgramTitle", "Practice program", "Oefenprogramma", "Übungsprogramm", "Programme d’entraînement", "Programa de práctica");
        Add("TrainProgramHelp", "A program changes tempo and time signature step by step, for example to build up speed.", "Een programma verandert stap voor stap het tempo en de maatsoort, bijvoorbeeld om snelheid op te bouwen.", "Ein Programm ändert Tempo und Taktart Schritt für Schritt, zum Beispiel um Geschwindigkeit aufzubauen.", "Un programme modifie pas à pas le tempo et la mesure, par exemple pour gagner en vitesse.", "Un programa cambia el tempo y el compás paso a paso, por ejemplo para ganar velocidad.");
        Add("EditInStudio", "Edit in Studio", "Bewerken in Studio", "Im Studio bearbeiten", "Modifier dans Studio", "Editar en Estudio");
        Add("ProgramEmptyTitle", "No program yet", "Nog geen programma", "Noch kein Programm", "Aucun programme", "Aún no hay programa");
        Add("BuildProgram", "Build a program in Studio", "Programma bouwen in Studio", "Programm im Studio erstellen", "Créer un programme dans Studio", "Crear un programa en Estudio");
        Add("ProgramIdle", "Not playing. Press Start to hear the program from the beginning.", "Speelt niet. Druk op Starten om het programma vanaf het begin te horen.", "Wird nicht gespielt. Starten drücken, um das Programm von Anfang an zu hören.", "À l’arrêt. Appuyez sur Démarrer pour entendre le programme depuis le début.", "Detenido. Pulse Iniciar para oír el programa desde el principio.");
        Add("TrainProgramChanged", "Status, chart and progress follow what is playing. The steps below are the program as you changed it in Studio; they are heard from the next Start.", "Status, grafiek en voortgang volgen wat nu speelt. De stappen hieronder zijn het programma zoals u het in Studio hebt gewijzigd; ze klinken vanaf de volgende Start.", "Status, Diagramm und Fortschritt folgen dem, was gerade spielt. Die Schritte unten sind das Programm, wie Sie es im Studio geändert haben; sie sind ab dem nächsten Start zu hören.", "L’état, le graphique et la progression suivent ce qui joue. Les étapes ci-dessous sont le programme tel que vous l’avez modifié dans Studio ; elles s’entendent au prochain démarrage.", "El estado, el gráfico y el progreso siguen lo que suena. Los pasos de abajo son el programa como lo cambió en Estudio; se oyen desde el próximo inicio.");
        Add("TrainProgramRemoved", "You removed this program in Studio. It keeps playing until you press Stop; after that the rhythm simply repeats.", "U hebt dit programma in Studio verwijderd. Het blijft spelen tot u op Stoppen drukt; daarna herhaalt het ritme zich gewoon.", "Sie haben dieses Programm im Studio entfernt. Es spielt weiter, bis Sie Stoppen drücken; danach wiederholt sich der Rhythmus einfach.", "Vous avez supprimé ce programme dans Studio. Il continue de jouer jusqu’à ce que vous appuyiez sur Arrêter ; ensuite, le rythme se répète simplement.", "Eliminó este programa en Estudio. Sigue sonando hasta que pulse Detener; después el ritmo simplemente se repite.");
        Add("UnitMs", "ms", "ms", "ms", "ms", "ms");
        Add("IncludeSilentHelp", "Beats the metronome stays silent on (gaps, muted layers, chance) still count, so you practise keeping time yourself.", "Tellen waarop de metronoom stil blijft (stiltes, gedempte lagen, kans) tellen toch mee, zodat u zelf de tijd leert houden.", "Zählzeiten, auf denen das Metronom schweigt (Lücken, stumme Ebenen, Zufall), zählen trotzdem, damit Sie selbst den Takt halten üben.", "Les temps où le métronome reste muet (silences, couches coupées, hasard) comptent quand même : vous travaillez la tenue du tempo.", "Los pulsos en los que el metrónomo calla (silencios, capas silenciadas, azar) también cuentan, para que practique mantener el tiempo usted mismo.");

        // Studio page (docs/design/pages-design.md).
        Add("StudioPurpose", "Editing “{0}”. Changes are saved as you make them. Press Stop, then Start, to hear them.", "“{0}” bewerken. Wijzigingen worden direct bewaard. Druk op Stoppen en daarna op Starten om ze te horen.", "Bearbeiten: „{0}“. Änderungen werden sofort gespeichert. Drücken Sie Stoppen und dann Starten, um sie zu hören.", "Modification de « {0} ». Les changements sont enregistrés au fur et à mesure. Appuyez sur Arrêter, puis sur Démarrer, pour les entendre.", "Editando «{0}». Los cambios se guardan al instante. Pulse Detener y luego Iniciar para oírlos.");
        Add("StudioLocked", "Editing is locked on the {0} page. Turn off “{1}” there to change the project.", "Bewerken is vergrendeld op de pagina {0}. Zet daar “{1}” uit om het project te wijzigen.", "Die Bearbeitung ist auf der Seite „{0}“ gesperrt. Schalten Sie dort „{1}“ aus, um das Projekt zu ändern.", "Les modifications sont verrouillées sur la page {0}. Désactivez-y « {1} » pour changer le projet.", "La edición está bloqueada en la página {0}. Desactive allí «{1}» para cambiar el proyecto.");
        Add("StudioEmptyTitle", "No lanes yet", "Nog geen lagen", "Noch keine Spuren", "Aucune piste", "Aún no hay pistas");
        Add("StudioEmptyBody", "A lane is a layer of clicks with its own pattern, sound and volume, played along with the main beat. Use two or more to build polyrhythms.", "Een laag is een extra reeks tikken met een eigen patroon, klank en volume, die meespeelt met de hoofdmaat. Gebruik er twee of meer voor polyritmes.", "Eine Spur ist eine zusätzliche Ebene aus Klicks mit eigenem Muster, Klang und eigener Lautstärke, die zum Hauptschlag mitspielt. Mit zwei oder mehr bauen Sie Polyrhythmen.", "Une piste est une couche de clics avec son propre motif, son propre son et son propre volume, jouée avec le temps principal. Utilisez-en deux ou plus pour créer des polyrythmies.", "Una pista es una capa de clics con su propio patrón, sonido y volumen, que suena junto al pulso principal. Use dos o más para crear polirritmos.");
        Add("LanePlain", "4 clicks over 4 beats", "4 tikken over 4 tellen", "4 Klicks auf 4 Schläge", "4 clics sur 4 temps", "4 clics en 4 tiempos");
        Add("LaneThreeInFour", "3 clicks over 4 beats (polyrhythm)", "3 tikken over 4 tellen (polyritme)", "3 Klicks auf 4 Schläge (Polyrhythmus)", "3 clics sur 4 temps (polyrythmie)", "3 clics en 4 tiempos (polirritmo)");
        Add("LaneThreeInThree", "3 clicks over 3 beats (polymeter)", "3 tikken over 3 tellen (polymaat)", "3 Klicks auf 3 Schläge (Polymetrik)", "3 clics sur 3 temps (polymétrie)", "3 clics en 3 tiempos (polimetría)");
        Add("LaneEuclidean", "Euclidean rhythm…", "Euclidisch ritme…", "Euklidischer Rhythmus …", "Rythme euclidien…", "Ritmo euclidiano…");
        Add("LaneField", "Lane {0}, {1}", "Laag {0}, {1}", "Spur {0}, {1}", "Piste {0}, {1}", "Pista {0}, {1}");
        Add("LaneBeatName", "Lane {0}, beat {1}, {2}", "Laag {0}, tel {1}, {2}", "Spur {0}, Zählzeit {1}, {2}", "Piste {0}, temps {1}, {2}", "Pista {0}, pulso {1}, {2}");
        Add("LaneGroupRhythm", "Rhythm", "Ritme", "Rhythmus", "Rythme", "Ritmo");
        Add("LaneGroupVariation", "Variation", "Variatie", "Variation", "Variation", "Variación");
        Add("LanePulses", "Clicks per cycle", "Tikken per cyclus", "Klicks pro Zyklus", "Clics par cycle", "Clics por ciclo");
        Add("LaneCycle", "Cycle length", "Cycluslengte", "Zykluslänge", "Durée du cycle", "Duración del ciclo");
        Add("LaneOffset", "Start offset", "Startverschuiving", "Startversatz", "Décalage de départ", "Desplazamiento inicial");
        Add("UnitQuarterNotes", "quarter notes", "kwartnoten", "Viertelnoten", "noires", "negras");
        Add("LaneRhythmHelp", "The pattern repeats every cycle; 4 quarter notes is one bar of 4/4. The start offset moves the whole lane later, or earlier with a minus sign.", "Het patroon herhaalt zich elke cyclus; 4 kwartnoten is één maat 4/4. De startverschuiving verplaatst de hele laag later, of eerder met een min-teken.", "Das Muster wiederholt sich in jedem Zyklus; 4 Viertelnoten sind ein 4/4-Takt. Der Startversatz verschiebt die ganze Spur nach hinten, mit Minuszeichen nach vorn.", "Le motif se répète à chaque cycle ; 4 noires font une mesure à 4/4. Le décalage de départ déplace toute la piste plus tard, ou plus tôt avec un signe moins.", "El patrón se repite en cada ciclo; 4 negras son un compás de 4/4. El desplazamiento inicial mueve toda la pista más tarde, o más pronto con un signo menos.");
        Add("LaneExactNote", "This lane places its clicks at exact positions. Edit them under “Custom beat positions” below.", "Deze laag plaatst haar tikken op exacte posities. Pas ze hieronder aan bij “Eigen tikposities”.", "Diese Spur setzt ihre Klicks auf exakte Positionen. Bearbeiten Sie sie unten unter „Eigene Zählzeitpositionen“.", "Cette piste place ses clics à des positions exactes. Modifiez-les plus bas sous « Positions personnalisées ».", "Esta pista coloca sus clics en posiciones exactas. Edítelas abajo, en «Posiciones personalizadas».");
        Add("CustomPositions", "Custom beat positions", "Eigen tikposities", "Eigene Zählzeitpositionen", "Positions personnalisées", "Posiciones personalizadas");
        Add("LanePan", "Pan", "Panorama", "Panorama", "Panoramique", "Panorama");
        Add("LaneSoundCaption", "Click sound", "Klikklank", "Klickklang", "Son du clic", "Sonido del clic");
        Add("PanLeft", "Left {0}", "Links {0}", "Links {0}", "Gauche {0}", "Izquierda {0}");
        Add("PanRight", "Right {0}", "Rechts {0}", "Rechts {0}", "Droite {0}", "Derecha {0}");
        Add("PanCenter", "Center", "Midden", "Mitte", "Centre", "Centro");
        Add("PercentValue", "{0}%", "{0}%", "{0} %", "{0} %", "{0} %");
        Add("LaneChance", "Chance each click plays", "Kans dat elke tik klinkt", "Wahrscheinlichkeit, dass jeder Klick erklingt", "Probabilité que chaque clic sonne", "Probabilidad de que suene cada clic");
        Add("LaneChanceHelp", "At 100% every click plays. Lower values leave clicks out at random, the same way every time (see Advanced).", "Bij 100% klinkt elke tik. Lagere waarden laten tikken willekeurig weg, telkens op dezelfde manier (zie Geavanceerd).", "Bei 100 % erklingt jeder Klick. Niedrigere Werte lassen Klicks zufällig aus, jedes Mal auf dieselbe Weise (siehe Erweitert).", "À 100 %, chaque clic sonne. Une valeur plus basse en omet au hasard, toujours de la même façon (voir Avancé).", "Al 100 %, suena cada clic. Un valor menor omite clics al azar, siempre del mismo modo (véase Avanzado).");
        Add("LaneSolo", "Solo", "Solo", "Solo", "Solo", "Solo");
        Add("LaneSoloHelp", "Solo: hear only the lanes marked Solo. The main beat is silent too. A muted lane does not count as Solo.", "Solo: alleen de lagen met Solo klinken. De hoofdmaat zwijgt dan ook. Een gedempte laag telt niet mee als Solo.", "Solo: nur die Spuren mit Solo erklingen. Auch der Hauptschlag schweigt. Eine stummgeschaltete Spur zählt nicht als Solo.", "Solo : seules les pistes en solo sonnent. Le temps principal se tait aussi. Une piste dont le son est coupé ne compte pas comme solo.", "Solo: solo suenan las pistas marcadas como Solo. El pulso principal también calla. Una pista silenciada no cuenta como Solo.");
        Add("LaneMuteHelp", "Silence this lane.", "Maak deze laag stil.", "Diese Spur stummschalten.", "Couper cette piste.", "Silenciar esta pista.");
        Add("LaneMore", "More actions", "Meer acties", "Weitere Aktionen", "Autres actions", "Más acciones");
        Add("LaneCopySuffix", " (copy)", " (kopie)", " (Kopie)", " (copie)", " (copia)");
        Add("LaneNameRequired", "A lane needs a name.", "Een laag heeft een naam nodig.", "Eine Spur braucht einen Namen.", "Une piste a besoin d’un nom.", "Una pista necesita un nombre.");
        Add("EuclideanHits", "Hits", "Tikken", "Klicks", "Clics", "Clics");
        Add("EuclideanSteps", "Steps", "Stappen", "Schritte", "Pas", "Pasos");
        Add("EuclideanExplain", "Spreads {0} hits as evenly as possible over {1} steps.", "Verdeelt {0} tikken zo gelijkmatig mogelijk over {1} stappen.", "Verteilt {0} Klicks so gleichmäßig wie möglich auf {1} Schritte.", "Répartit {0} clics aussi régulièrement que possible sur {1} pas.", "Reparte {0} clics lo más uniformemente posible en {1} pasos.");
        Add("EuclideanInvalid", "Hits cannot be more than steps.", "Er kunnen niet meer tikken zijn dan stappen.", "Es kann nicht mehr Klicks als Schritte geben.", "Il ne peut pas y avoir plus de clics que de pas.", "No puede haber más clics que pasos.");
        Add("EuclideanWhole", "Enter whole numbers for hits, steps and rotation.", "Voer hele getallen in voor tikken, stappen en rotatie.", "Geben Sie ganze Zahlen für Klicks, Schritte und Rotation ein.", "Saisissez des nombres entiers pour les clics, les pas et la rotation.", "Introduzca números enteros para clics, pasos y rotación.");
        Add("EuclideanPreviewName", "Pattern preview", "Voorbeeld van het patroon", "Mustervorschau", "Aperçu du motif", "Vista previa del patrón");
        Add("Create", "Create", "Maken", "Erstellen", "Créer", "Crear");
        Add("Advanced", "Advanced", "Geavanceerd", "Erweitert", "Avancé", "Avanzado");
        Add("AdvancedHelp", "Chance in a lane leaves clicks out at random. The pattern number decides which ones, so the same number always plays the same pattern.", "Met Kans in een laag vallen tikken willekeurig weg. Het patroonnummer bepaalt welke, dus hetzelfde nummer speelt altijd hetzelfde patroon.", "Mit der Wahrscheinlichkeit einer Spur entfallen Klicks zufällig. Die Musternummer bestimmt, welche – dieselbe Nummer spielt also immer dasselbe Muster.", "La probabilité d’une piste omet des clics au hasard. Le numéro de motif décide lesquels : le même numéro donne toujours le même motif.", "La probabilidad de una pista omite clics al azar. El número de patrón decide cuáles, así que el mismo número siempre da el mismo patrón.");
        Add("SeedLabel", "Random pattern number", "Nummer van het willekeurige patroon", "Nummer des Zufallsmusters", "Numéro du motif aléatoire", "Número del patrón aleatorio");
        Add("SeedInvalid", "Enter a whole number, for example 42.", "Voer een geheel getal in, bijvoorbeeld 42.", "Geben Sie eine ganze Zahl ein, zum Beispiel 42.", "Saisissez un nombre entier, par exemple 42.", "Introduzca un número entero, por ejemplo 42.");

        // Studio: practice-program steps and exact positions (docs/design/pages-design.md).
        Add("StepsEmptyTitle", "No steps yet", "Nog geen stappen", "Noch keine Schritte", "Aucune étape", "Aún no hay pasos");
        Add("StepsEmptyBody", "A program plays one step after another, each with its own tempo, length and time signature. Add a step to start building one.", "Een programma speelt de ene stap na de andere, elk met een eigen tempo, lengte en maatsoort. Voeg een stap toe om er een te bouwen.", "Ein Programm spielt einen Schritt nach dem anderen, jeder mit eigenem Tempo, eigener Länge und eigener Taktart. Fügen Sie einen Schritt hinzu, um eines aufzubauen.", "Un programme joue une étape après l’autre, chacune avec son propre tempo, sa durée et sa mesure. Ajoutez une étape pour en créer un.", "Un programa reproduce un paso tras otro, cada uno con su propio tempo, duración y compás. Añada un paso para empezar a crear uno.");
        Add("StepLimit", "A program can have at most 1024 steps.", "Een programma kan maximaal 1024 stappen hebben.", "Ein Programm kann höchstens 1024 Schritte haben.", "Un programme peut avoir au maximum 1024 étapes.", "Un programa puede tener como máximo 1024 pasos.");
        Add("StepNameCaption", "Step {0} · name", "Stap {0} · naam", "Schritt {0} · Name", "Étape {0} · nom", "Paso {0} · nombre");
        Add("StepField", "Step {0}, {1}", "Stap {0}, {1}", "Schritt {0}, {1}", "Étape {0}, {1}", "Paso {0}, {1}");
        Add("StepRampHelp", "The tempo moves evenly from the first value to the second during each repeat of the step. “{0}” changes it by the same amount every second, “{1}” by the same amount every beat.", "Het tempo verandert gelijkmatig van de eerste naar de tweede waarde tijdens elke herhaling van de stap. “{0}” verandert het met hetzelfde bedrag per seconde, “{1}” met hetzelfde bedrag per tel.", "Das Tempo ändert sich während jeder Wiederholung des Schritts gleichmäßig vom ersten zum zweiten Wert. „{0}“ ändert es in jeder Sekunde um denselben Betrag, „{1}“ auf jeder Zählzeit um denselben Betrag.", "Le tempo évolue régulièrement de la première à la seconde valeur pendant chaque répétition de l’étape. « {0} » le change du même montant chaque seconde, « {1} » du même montant à chaque temps.", "El tempo pasa de forma uniforme del primer valor al segundo durante cada repetición del paso. «{0}» lo cambia en la misma cantidad cada segundo; «{1}», en la misma cantidad cada pulso.");
        Add("UnitBpm", "BPM", "BPM", "BPM", "BPM", "BPM");
        Add("StepGapSwitch", "Leave some bars silent", "Sommige maten stil laten", "Einige Takte stumm lassen", "Laisser certaines mesures silencieuses", "Dejar algunos compases en silencio");
        Add("StepGapSentence", "Play {0} bars, then {1} bars silent", "Speel {0} maten, daarna {1} maten stil", "{0} Takte spielen, dann {1} Takte stumm", "Jouer {0} mesures, puis {1} mesures en silence", "Tocar {0} compases y luego {1} compases en silencio");
        Add("StepGapHelp", "The click plays for the first bars, then stops for the next, and so on. You keep time yourself while it is silent.", "De klik speelt de eerste maten, zwijgt dan de volgende, en zo verder. Tijdens de stilte houdt u zelf de tijd.", "Der Klick spielt die ersten Takte und schweigt dann für die nächsten, und so weiter. Während der Stille halten Sie den Takt selbst.", "Le clic joue pendant les premières mesures, puis se tait pendant les suivantes, et ainsi de suite. Pendant le silence, vous tenez le tempo vous-même.", "El clic suena durante los primeros compases y calla durante los siguientes, y así sucesivamente. Durante el silencio mantiene usted el tiempo.");
        Add("StepMeterGrouped", "This project groups its beats (for example 2+2+3), so every step uses the project’s time signature. To give a step another one, clear the grouping.", "Dit project groepeert zijn tellen (bijvoorbeeld 2+2+3), dus elke stap gebruikt de maatsoort van het project. Wis de groepering om een stap een andere te geven.", "Dieses Projekt gruppiert seine Zählzeiten (zum Beispiel 2+2+3), daher verwendet jeder Schritt die Taktart des Projekts. Um einem Schritt eine andere zu geben, löschen Sie die Gruppierung.", "Ce projet regroupe ses temps (par exemple 2+2+3) : chaque étape utilise donc la mesure du projet. Pour en donner une autre à une étape, effacez le groupement.", "Este proyecto agrupa sus pulsos (por ejemplo 2+2+3), así que cada paso usa el compás del proyecto. Para darle otro a un paso, borre la agrupación.");
        Add("ClearGrouping", "Clear grouping", "Groepering wissen", "Gruppierung löschen", "Effacer le groupement", "Borrar la agrupación");
        Add("ProgramTooLong", "A program can be at most {0} bars long, and have at most {1} steps once repeats are counted. Shorten a step or lower its repeats.", "Een programma mag hooguit {0} maten lang zijn en hooguit {1} stappen hebben als herhalingen meetellen. Maak een stap korter of verlaag het aantal herhalingen.", "Ein Programm darf höchstens {0} Takte lang sein und höchstens {1} Schritte haben, wenn Wiederholungen mitgezählt werden. Kürzen Sie einen Schritt oder verringern Sie seine Wiederholungen.", "Un programme peut durer au maximum {0} mesures et compter au maximum {1} étapes, répétitions comprises. Raccourcissez une étape ou réduisez ses répétitions.", "Un programa puede durar como máximo {0} compases y tener como máximo {1} pasos contando las repeticiones. Acorte un paso o reduzca sus repeticiones.");
        Add("PositionsHelp", "Place each click exactly, measured in quarter notes from the start of the cycle. Use fractions such as 1/3 for triplets and other uneven spacing.", "Plaats elke tik precies, gemeten in kwartnoten vanaf het begin van de cyclus. Gebruik breuken zoals 1/3 voor triolen en andere ongelijke verdelingen.", "Setzen Sie jeden Klick genau, gemessen in Viertelnoten ab Zyklusbeginn. Verwenden Sie Brüche wie 1/3 für Triolen und andere ungleichmäßige Abstände.", "Placez chaque clic avec précision, en noires depuis le début du cycle. Utilisez des fractions comme 1/3 pour les triolets et autres espacements irréguliers.", "Coloque cada clic con exactitud, medido en negras desde el inicio del ciclo. Use fracciones como 1/3 para tresillos y otros espaciados desiguales.");
        Add("PositionsConvert", "Convert the pattern to positions", "Patroon omzetten naar posities", "Muster in Positionen umwandeln", "Convertir le motif en positions", "Convertir el patrón en posiciones");
        Add("PositionsConvertHelp", "The lane keeps playing the same clicks, now at positions you can move one by one. Undo brings the pattern back.", "De laag speelt dezelfde tikken, nu op posities die u een voor een kunt verschuiven. Met Ongedaan maken komt het patroon terug.", "Die Spur spielt dieselben Klicks weiter, nun an Positionen, die Sie einzeln verschieben können. Mit Rückgängig kehrt das Muster zurück.", "La piste joue toujours les mêmes clics, désormais à des positions que vous pouvez déplacer une par une. Annuler rétablit le motif.", "La pista sigue tocando los mismos clics, ahora en posiciones que puede mover una a una. Deshacer recupera el patrón.");
        Add("PositionsAdd", "Add position", "Positie toevoegen", "Position hinzufügen", "Ajouter une position", "Añadir posición");
        Add("PositionLimit", "A lane can have at most 256 positions.", "Een laag kan maximaal 256 posities hebben.", "Eine Spur kann höchstens 256 Positionen haben.", "Une piste peut avoir au maximum 256 positions.", "Una pista puede tener como máximo 256 posiciones.");
        Add("PositionField", "Position", "Positie", "Position", "Position", "Posición");
        Add("PositionName", "Position {0}", "Positie {0}", "Position {0}", "Position {0}", "Posición {0}");
        Add("PositionTied", "tied", "gebonden", "gebunden", "liée", "ligado");
        Add("PositionInvalid", "Enter a position as a whole number, a fraction such as 1/3, or a decimal such as 0.5.", "Voer een positie in als geheel getal, een breuk zoals 1/3 of een decimaal getal zoals 0,5.", "Geben Sie eine Position als ganze Zahl, als Bruch wie 1/3 oder als Dezimalzahl wie 0,5 ein.", "Saisissez une position sous forme d’entier, de fraction comme 1/3 ou de décimal comme 0,5.", "Introduzca una posición como número entero, como fracción (por ejemplo 1/3) o como decimal (por ejemplo 0,5).");
        Add("PositionRange", "A position must be at least 0 and less than the cycle length ({0} quarter notes).", "Een positie moet minstens 0 zijn en kleiner dan de cycluslengte ({0} kwartnoten).", "Eine Position muss mindestens 0 und kleiner als die Zykluslänge ({0} Viertelnoten) sein.", "Une position doit être au moins 0 et inférieure à la durée du cycle ({0} noires).", "Una posición debe ser al menos 0 y menor que la duración del ciclo ({0} negras).");
        Add("PositionTaken", "Another click is already at that position. Choose a different one.", "Er ligt al een andere tik op die positie. Kies een andere.", "An dieser Position liegt schon ein anderer Klick. Wählen Sie eine andere.", "Un autre clic se trouve déjà à cette position. Choisissez-en une autre.", "Ya hay otro clic en esa posición. Elija otra.");
        Add("PositionPrecise", "That position is too precise. Use fewer decimals or a simpler fraction.", "Die positie is te nauwkeurig. Gebruik minder decimalen of een eenvoudigere breuk.", "Diese Position ist zu genau. Verwenden Sie weniger Nachkommastellen oder einen einfacheren Bruch.", "Cette position est trop précise. Utilisez moins de décimales ou une fraction plus simple.", "Esa posición es demasiado precisa. Use menos decimales o una fracción más simple.");
        Add("PositionGone", "An earlier change moved or removed that position. The list now shows what is there.", "Een eerdere wijziging heeft die positie verplaatst of verwijderd. De lijst toont nu wat er staat.", "Eine frühere Änderung hat diese Position verschoben oder entfernt. Die Liste zeigt jetzt, was vorhanden ist.", "Une modification précédente a déplacé ou supprimé cette position. La liste affiche maintenant ce qui s’y trouve.", "Un cambio anterior movió o quitó esa posición. La lista muestra ahora lo que hay.");
        Add("PositionStrength", "Strength", "Sterkte", "Stärke", "Force", "Fuerza");
        Add("PositionTie", "Tied: no new click here", "Gebonden: hier geen nieuwe tik", "Gebunden: hier kein neuer Klick", "Liée : pas de nouveau clic ici", "Ligado: sin clic nuevo aquí");
        Add("PositionChance", "Chance this click plays", "Kans dat deze tik klinkt", "Wahrscheinlichkeit, dass dieser Klick erklingt", "Probabilité que ce clic sonne", "Probabilidad de que suene este clic");
        Add("StepLength", "Length", "Lengte", "Länge", "Durée", "Duración");
        Add("StepBarsPlayed", "Bars played", "Gespeelde maten", "Gespielte Takte", "Mesures jouées", "Compases tocados");
        Add("StepNameRequired", "A step needs a name.", "Een stap heeft een naam nodig.", "Ein Schritt braucht einen Namen.", "Une étape a besoin d’un nom.", "Un paso necesita un nombre.");

        // Tap to start (docs/CAPABILITIES.md): taps set the tempo and then start the metronome.
        Add("TapStart", "Tap to start", "Start met tikken", "Durch Tippen starten", "Démarrer en tapant", "Marcar para iniciar");
        Add("TapStartHelp", "Tap along {0} times and the metronome starts at your tempo.", "Tik {0} keer mee en de metronoom start op uw tempo.", "Tippen Sie {0}-mal mit, dann startet das Metronom in Ihrem Tempo.", "Tapez {0} fois en rythme : le métronome démarre à votre tempo.", "Marque el ritmo {0} veces y el metrónomo empieza con su tempo.");
        Add("TapStartProgramHelp", "Tap along {0} times. The first step starts at your tempo and the other steps keep their proportions.", "Tik {0} keer mee. De eerste stap start op uw tempo en de andere stappen behouden hun verhouding.", "Tippen Sie {0}-mal mit. Der erste Schritt startet in Ihrem Tempo, die anderen Schritte behalten ihr Verhältnis.", "Tapez {0} fois en rythme. La première étape démarre à votre tempo et les autres gardent leurs proportions.", "Marque el ritmo {0} veces. El primer paso empieza con su tempo y los demás mantienen sus proporciones.");
        Add("TapStartActive", "Tap along with TAP or the T key. A tap that is off the beat starts the count again. Stop, Esc or this button cancels.", "Tik mee met TIK of de T-toets. Een tik die niet in de maat valt, begint het tellen opnieuw. Stoppen, Esc of deze knop annuleert.", "Tippen Sie mit TAP oder der Taste T. Wer aus dem Takt kommt, beginnt die Zählung neu. Stoppen, Esc oder diese Schaltfläche bricht ab.", "Tapez avec TAP ou la touche T. Une frappe hors du rythme relance le compte. Arrêter, Échap ou ce bouton annule.", "Marque con TAP o la tecla T. Un toque fuera de ritmo reinicia la cuenta. Detener, Esc o este botón lo cancela.");
        Add("TapStartStopFirst", "Press Stop first, then tap to start.", "Druk eerst op Stoppen en start daarna met tikken.", "Zuerst auf Stoppen drücken, dann durch Tippen starten.", "Appuyez d’abord sur Arrêter, puis démarrez en tapant.", "Pulse primero Detener y luego marque para iniciar.");
        Add("TapStartMonitoring", "Tap to start cannot check that the audio output stays connected right now, so it is off. Start still works.", "Start met tikken kan nu niet controleren of de audio-uitvoer verbonden blijft en staat daarom uit. Starten werkt nog.", "Durch Tippen starten kann gerade nicht prüfen, ob die Audioausgabe verbunden bleibt, und ist deshalb aus. Starten funktioniert weiterhin.", "Le démarrage en tapant ne peut pas vérifier pour l’instant que la sortie audio reste connectée ; il est donc désactivé. Démarrer fonctionne toujours.", "Marcar para iniciar no puede comprobar ahora que la salida de audio siga conectada, así que está desactivado. Iniciar sigue funcionando.");
        Add("TapStartCount", "{0} of {1} taps", "{0} van {1} tikken", "{0}/{1} getippt", "{0}/{1} frappes", "{0} de {1} toques");
        Add("TapStartRejected", "Tap again", "Tik opnieuw", "Nochmal tippen", "Tapez encore", "Marque otra vez");
        Add("TapStartStarting", "Starting…", "Starten…", "Startet…", "Démarrage…", "Iniciando…");
        Add("TapStartCancelled", "Tap to start was cancelled.", "Start met tikken is geannuleerd.", "Durch Tippen starten wurde abgebrochen.", "Le démarrage en tapant a été annulé.", "Se canceló Marcar para iniciar.");
        Add("TapStartOutputChanged", "The audio output changed, so tap to start was cancelled.", "De audio-uitvoer is gewijzigd; start met tikken is geannuleerd.", "Die Audioausgabe hat sich geändert; Starten durch Tippen wurde abgebrochen.", "La sortie audio a changé ; le démarrage en tapant est annulé.", "La salida de audio cambió; se canceló Marcar para iniciar.");
        Add("TapStartRange", "Those taps would put a tempo outside 1–1000 BPM. Switch Tap to start on again and tap a different tempo.", "Met deze tikken komt een tempo buiten 1–1000 BPM. Zet Start met tikken weer aan en tik een ander tempo.", "Dieses Tippen ergäbe ein Tempo außerhalb von 1–1000 BPM. Schalten Sie Durch Tippen starten wieder ein und tippen Sie ein anderes Tempo.", "Ces frappes donneraient un tempo hors de 1–1000 BPM. Réactivez Démarrer en tapant et tapez un autre tempo.", "Estos toques darían un tempo fuera de 1–1000 BPM. Active de nuevo Marcar para iniciar y marque otro tempo.");
        Add("TapStartScaled", "The program now starts at {0} BPM; its other steps keep their proportions.", "Het programma start nu op {0} BPM; de andere stappen behouden hun verhouding.", "Das Programm startet jetzt mit {0} BPM; die anderen Schritte behalten ihr Verhältnis.", "Le programme démarre maintenant à {0} BPM ; les autres étapes gardent leurs proportions.", "El programa empieza ahora a {0} BPM; los demás pasos mantienen sus proporciones.");
        Add("TapStartCountField", "Taps to start", "Tikken om te starten", "Zum Start tippen", "Frappes pour démarrer", "Toques para iniciar");
        Add("TapStartCountHelp", "From 2 to 16 steady taps. Used the next time you switch Tap to start on.", "Van 2 tot 16 gelijkmatige tikken. Geldt de volgende keer dat u Start met tikken aanzet.", "2 bis 16 Mal gleichmäßig tippen. Gilt beim nächsten Einschalten von Durch Tippen starten.", "De 2 à 16 frappes régulières. S’applique à la prochaine activation de Démarrer en tapant.", "De 2 a 16 toques regulares. Se usa la próxima vez que active Marcar para iniciar.");
        Add("UnitTaps", "taps", "tikken", "Mal", "frappes", "toques");
        Add("HelpTapStart", "Switch on Tap to start, then tap TAP, or press T, in the beat you want. After the chosen number of steady taps the metronome starts at that tempo.", "Zet Start met tikken aan en tik dan op TIK, of druk op T, in de gewenste maat. Na het gekozen aantal gelijkmatige tikken start de metronoom op dat tempo.", "Schalten Sie Durch Tippen starten ein und tippen Sie im gewünschten Takt auf TAP oder drücken Sie T. Nach der eingestellten Anzahl gleichmäßigen Tippens startet das Metronom in diesem Tempo.", "Activez Démarrer en tapant, puis tapez TAP, ou appuyez sur T, au rythme voulu. Après le nombre choisi de frappes régulières, le métronome démarre à ce tempo.", "Active Marcar para iniciar y luego pulse TAP, o la tecla T, al ritmo que quiera. Tras el número elegido de toques regulares, el metrónomo empieza con ese tempo.");
        Add("ShortcutTap", "Tap the tempo", "Het tempo tikken", "Tempo tippen", "Taper le tempo", "Marcar el tempo");
        // The Help panel (HelpContent.cs): a quick start, what plays at once, and a short musical reference. Every control is named
        // by the string it shows, passed in as a placeholder, so the Help follows the window in each language.
        Add("HelpQuickStart", "Quick start", "Snel starten", "Schnellstart", "Prise en main", "Inicio rápido");
        Add("HelpStepOutput",
            "The first time, the app uses the Windows default output. To use other speakers or headphones, press {0} at the bottom. {1} is grey until an output is chosen.",
            "De eerste keer gebruikt de app het standaard uitvoerapparaat van Windows. Voor andere luidsprekers of een koptelefoon drukt u onderaan op {0}. {1} blijft grijs zolang er geen uitvoer is gekozen.",
            "Beim ersten Mal nutzt die App die Windows-Standardausgabe. Für andere Lautsprecher oder Kopfhörer drücken Sie unten auf {0}. {1} bleibt grau, bis eine Ausgabe gewählt ist.",
            "La première fois, l’application utilise la sortie par défaut de Windows. Pour d’autres haut-parleurs ou un casque, appuyez sur {0} en bas. {1} reste grisé tant qu’aucune sortie n’est choisie.",
            "La primera vez, la aplicación usa la salida predeterminada de Windows. Para otros altavoces o auriculares, pulse {0} abajo. {1} sigue en gris hasta que se elige una salida.");
        Add("HelpStepStart",
            "Press {0}, or the {1} key when no button has the focus. A new project counts in one bar first, then clicks.",
            "Druk op {0}, of op {1} als geen knop de focus heeft. Een nieuw project telt eerst één maat af, daarna volgen de tikken.",
            "Drücken Sie {0} oder die {1}, wenn keine Schaltfläche den Fokus hat. Ein neues Projekt zählt zuerst einen Takt ein, dann folgen die Klicks.",
            "Appuyez sur {0}, ou sur la touche {1} si aucun bouton n’a le focus. Un nouveau projet commence par une mesure de décompte, puis viennent les clics.",
            "Pulse {0} o la tecla {1} si ningún botón tiene el foco. Un proyecto nuevo cuenta primero un compás de entrada y después suenan los clics.");
        Add("HelpStepTempo",
            "Click the big number, type your tempo and choose {2}. Or press − and + (hold to repeat; with {0} they move by 10), or tap {1} at least twice in time with your beat.",
            "Klik op het grote getal, typ uw tempo en kies {2}. Of druk op − en + (ingedrukt houden herhaalt; met {0} gaat het in stappen van 10), of tik minstens twee keer op {1} in de maat van uw tempo.",
            "Klicken Sie auf die große Zahl, geben Sie Ihr Tempo ein und wählen Sie {2}. Oder drücken Sie − und + (gedrückt halten wiederholt; mit {0} in Zehnerschritten) oder tippen Sie mindestens zweimal auf {1} im Takt Ihres Tempos.",
            "Cliquez sur le grand nombre, saisissez votre tempo et choisissez {2}. Ou appuyez sur − et + (maintenir répète ; avec {0}, par pas de 10), ou tapez au moins deux fois sur {1} en rythme avec votre tempo.",
            "Haga clic en el número grande, escriba su tempo y elija {2}. O pulse − y + (mantener repite; con {0}, de 10 en 10), o pulse {1} al menos dos veces al ritmo de su tempo.");
        Add("HelpStepMeter",
            "Press the time signature below the circle (4/4 to begin with) and choose another, such as 3/4 or 6/8. {0} builds any other one and sets the count-in.",
            "Druk op de maatsoort onder de cirkel (eerst 4/4) en kies een andere, zoals 3/4 of 6/8. Met {0} stelt u elke andere maatsoort samen en kiest u ook het aftellen.",
            "Drücken Sie unter dem Kreis auf die Taktart (zunächst 4/4) und wählen Sie eine andere, etwa 3/4 oder 6/8. Mit {0} stellen Sie jede andere Taktart zusammen und legen auch das Einzählen fest.",
            "Appuyez sur la mesure sous le cercle (4/4 au départ) et choisissez-en une autre, comme 3/4 ou 6/8. {0} permet de composer toute autre mesure et de régler le décompte.",
            "Pulse el compás bajo el círculo (4/4 al principio) y elija otro, como 3/4 o 6/8. {0} crea cualquier otro compás y ajusta la entrada.");
        Add("HelpStepStrength",
            "Tap a beat under {0} to change its strength: {1}, {2}, {3} or {4}. The first beat starts {1}.",
            "Tik op een tel onder {0} om de sterkte te wijzigen: {1}, {2}, {3} of {4}. De eerste tel is in het begin {1}.",
            "Tippen Sie unter {0} auf eine Zählzeit, um ihre Betonung zu ändern: {1}, {2}, {3} oder {4}. Die erste Zählzeit ist anfangs {1}.",
            "Touchez un temps sous {0} pour changer sa force : {1}, {2}, {3} ou {4}. Le premier temps est d’abord {1}.",
            "Toque un pulso bajo {0} para cambiar su intensidad: {1}, {2}, {3} o {4}. El primer pulso empieza en {1}.");
        Add("HelpTapStartLimits",
            "Choose 2 to 16 taps in the Tempo panel. It works only while the metronome is stopped and an output is chosen. An uneven tap, or a pause of more than four seconds, starts the count again. Stop cancels it, and so does Esc when no panel is open. The metronome starts a moment after your last tap, not exactly on it.",
            "Kies 2 tot 16 tikken in het paneel Tempo. Het werkt alleen als de metronoom gestopt is en er een uitvoer is gekozen. Een tik die niet in de maat valt, of een pauze van meer dan vier seconden, begint het tellen opnieuw. Stoppen annuleert het, en Esc ook als geen paneel openstaat. De metronoom start een moment na uw laatste tik, niet precies erop.",
            "Wie oft getippt wird (2 bis 16 Mal), stellen Sie im Tempo-Fenster ein. Es funktioniert nur, solange das Metronom gestoppt und eine Ausgabe gewählt ist. Tippen Sie unregelmäßig oder pausieren Sie länger als vier Sekunden, beginnt die Zählung neu. Stoppen bricht es ab, Esc ebenfalls, wenn kein Zusatzfenster offen ist. Das Metronom startet einen Moment nach Ihrem letzten Tippen, nicht genau darauf.",
            "Choisissez 2 à 16 frappes dans le panneau Tempo. Cela ne marche que lorsque le métronome est arrêté et qu’une sortie est choisie. Une frappe irrégulière, ou une pause de plus de quatre secondes, relance le compte. Arrêter l’annule, et Échap aussi quand aucun panneau n’est ouvert. Le métronome démarre un instant après votre dernière frappe, pas exactement sur elle.",
            "Elija de 2 a 16 toques en el panel Tempo. Solo funciona con el metrónomo detenido y una salida elegida. Un toque irregular, o una pausa de más de cuatro segundos, reinicia la cuenta. Detener lo cancela, y Esc también cuando no hay ningún panel abierto. El metrónomo empieza un instante después de su último toque, no exactamente sobre él.");
        Add("HelpPlaying",
            "{0} holds your place and {1} carries on from there. {2} goes back to the beginning, so the next {1} plays the count-in again. {3} silences the clicks while the count goes on.",
            "{0} houdt uw plaats vast en {1} gaat vanaf daar verder. {2} gaat terug naar het begin, dus bij de volgende {1} hoort u het aftellen opnieuw. {3} maakt de tikken stil terwijl het tellen doorgaat.",
            "{0} hält Ihre Stelle fest, {1} macht dort weiter. {2} geht an den Anfang zurück, danach spielt {1} das Einzählen wieder ab. {3} schaltet die Klicks stumm, während die Zählung weiterläuft.",
            "{0} garde votre place et {1} reprend à partir de là. {2} revient au début, donc {1} rejoue le décompte. {3} rend les clics muets pendant que le compte continue.",
            "{0} guarda el punto en que está; {1} sigue desde ahí. {2} vuelve al principio, así que {1} vuelve a tocar la entrada. {3} apaga los clics mientras la cuenta continúa.");
        Add("HelpLive",
            "Sound and beat strength change at once. Tempo, time signature, note value, subdivision and swing change from the next beat. The count-in, the {2} limits and everything in {3} are used after {0}, then {1}.",
            "Klank en telsterkte veranderen meteen. Tempo, maatsoort, nootwaarde, onderverdeling en swing veranderen vanaf de volgende tel. Het aftellen, de limieten van {2} en alles in {3} gelden na {0} en daarna {1}.",
            "Klang und Betonung ändern sich sofort. Tempo, Taktart, Notenwert, Unterteilung und Swing ändern sich ab der nächsten Zählzeit. Das Einzählen, die Grenzen im {2} und alles im {3} gelten nach {0} und dann {1}.",
            "Le son et la force des temps changent tout de suite. Le tempo, la mesure, la valeur de note, la subdivision et le swing changent à partir du temps suivant. Le décompte, les limites du {2} et tout ce qui se fait dans {3} s’appliquent après {0}, puis {1}.",
            "El sonido y la intensidad cambian al instante. El tempo, el compás, la figura, la subdivisión y el swing cambian desde el siguiente pulso. La entrada, los límites del {2} y todo lo de {3} se aplican tras {0} y luego {1}.");
        Add("HelpProgram",
            "A project with a practice program takes its tempo and time signature from the program, so the tempo and time signature controls are off. Change them in {0}.",
            "Een project met een oefenprogramma haalt tempo en maatsoort uit dat programma, dus de bediening voor tempo en maatsoort staat uit. Wijzig ze in {0}.",
            "Ein Projekt mit Übungsprogramm übernimmt Tempo und Taktart vom Programm, deshalb sind die Bedienelemente für Tempo und Taktart ausgeschaltet. Ändern Sie beides im {0}.",
            "Un projet avec un programme d’entraînement reprend son tempo et sa mesure au programme : les commandes de tempo et de mesure sont donc désactivées. Modifiez-les dans {0}.",
            "Un proyecto con programa de práctica toma su tempo y su compás del programa, así que los controles de tempo y de compás están desactivados. Cámbielos en {0}.");
        Add("HelpShortcutScope",
            "Shortcuts work only in this window, and T only on {2} with no panel open. {0} starts or pauses only when no button has the focus (on a button it presses that button). While you type in a box, {0}, T and F do nothing; {1} + M, {1} + S and {1} + O still work.",
            "Sneltoetsen werken alleen in dit venster, en T alleen in {2} zonder open paneel. {0} start of pauzeert alleen als geen knop de focus heeft (op een knop drukt het die knop in). Terwijl u in een vak typt, doen {0}, T en F niets; {1} + M, {1} + S en {1} + O werken wel.",
            "Tastenkürzel gelten nur in diesem Fenster, T nur unter {2} ohne offenes Zusatzfenster. {0} startet oder pausiert nur, wenn keine Schaltfläche den Fokus hat (auf einer Schaltfläche drückt sie diese Schaltfläche). Beim Schreiben in ein Feld bewirken {0}, T und F nichts; {1} + M, {1} + S und {1} + O funktionieren weiterhin.",
            "Les raccourcis ne fonctionnent que dans cette fenêtre, et T seulement dans {2} sans panneau ouvert. {0} démarre ou met en pause seulement si aucun bouton n’a le focus (sur un bouton, cette touche appuie sur ce bouton). Quand vous écrivez dans un champ, {0}, T et F ne font rien ; {1} + M, {1} + S et {1} + O fonctionnent toujours.",
            "Los atajos solo funcionan en esta ventana, y T solo en {2} sin ningún panel abierto. {0} inicia o pausa solo si ningún botón tiene el foco (en un botón, pulsa ese botón). Mientras escribe en un cuadro, {0}, T y F no hacen nada; {1} + M, {1} + S y {1} + O siguen funcionando.");
        Add("HelpReference", "Musical reference", "Muzikale uitleg", "Musikalische Grundlagen", "Repères musicaux", "Referencia musical");
        Add("HelpBpmTitle", "BPM and the note value", "BPM en de nootwaarde", "BPM und Notenwert", "BPM et valeur de note", "BPM y figura de la nota");
        Add("HelpBpm",
            "BPM counts one kind of note per minute. With quarter notes, 120 BPM is 120 quarter notes a minute. Choose the note with {0} in the Tempo panel (click the big number).",
            "BPM telt één soort noot per minuut. Met kwartnoten is 120 BPM gelijk aan 120 kwartnoten per minuut. Kies de noot bij {0} in het paneel Tempo (klik op het grote getal).",
            "BPM zählt eine Notensorte pro Minute. Mit Viertelnoten sind 120 BPM 120 Viertelnoten pro Minute. Die Note wählen Sie unter {0} im Tempo-Fenster (auf die große Zahl klicken).",
            "Le BPM compte un seul type de note par minute. Avec des noires, 120 BPM font 120 noires par minute. Choisissez la note avec {0} dans le panneau Tempo (cliquez sur le grand nombre).",
            "BPM cuenta un tipo de nota por minuto. Con negras, 120 BPM son 120 negras por minuto. Elija la nota en {0}, dentro del panel Tempo (haga clic en el número grande).");
        Add("HelpBpmExample",
            "Example: in 6/8, 80 BPM with dotted quarter notes is as fast as 240 BPM with eighth notes.",
            "Voorbeeld: in 6/8 is 80 BPM met gepunte kwartnoten even snel als 240 BPM met achtste noten.",
            "Beispiel: Im 6/8-Takt sind 80 BPM mit punktierten Viertelnoten so schnell wie 240 BPM mit Achtelnoten.",
            "Exemple : en 6/8, 80 BPM en noires pointées vont aussi vite que 240 BPM en croches.",
            "Ejemplo: en 6/8, 80 BPM con negras con puntillo van tan rápido como 240 BPM con corcheas.");
        Add("HelpMeterTitle", "Time signature and the click", "Maatsoort en de tik", "Taktart und Klick", "Mesure et clic", "Compás y clic");
        Add("HelpMeter",
            "The top number is how many beats a bar has. The bottom number says which note one beat is: 4 is a quarter note, 8 an eighth note. Choosing a time signature gives one click for every written beat, as long as Subdivision is 1.",
            "Het bovenste getal zegt hoeveel tellen een maat heeft. Het onderste getal zegt welke noot één tel is: 4 is een kwartnoot, 8 een achtste noot. Een maatsoort kiezen geeft één tik per geschreven tel, zolang Onderverdeling 1 is.",
            "Die obere Zahl sagt, wie viele Zählzeiten ein Takt hat. Die untere Zahl sagt, welche Note eine Zählzeit ist: 4 steht für eine Viertelnote, 8 für eine Achtelnote. Wer eine Taktart wählt, bekommt einen Klick pro notierter Zählzeit, solange die Unterteilung 1 ist.",
            "Le chiffre du haut dit combien de temps compte une mesure. Le chiffre du bas dit quelle note vaut un temps : 4 pour une noire, 8 pour une croche. Choisir une mesure donne un clic par temps écrit, tant que la subdivision est à 1.",
            "El número de arriba indica cuántos pulsos tiene un compás. El de abajo indica qué nota es un pulso: 4 es una negra, 8 una corchea. Al elegir un compás suena un clic por cada pulso escrito, mientras la subdivisión sea 1.");
        Add("HelpMeterExample",
            "Example: with Subdivision 1, 6/8 clicks six times a bar. To feel it in two instead, set the note value to dotted quarter in the Tempo panel and type a tempo such as 80: two clicks a bar.",
            "Voorbeeld: met Onderverdeling 1 tikt 6/8 zes keer per maat. Wilt u het in twee voelen, zet dan de nootwaarde op gepunte kwartnoot in het paneel Tempo en typ een tempo zoals 80: twee tikken per maat.",
            "Beispiel: Bei Unterteilung 1 klickt 6/8 sechsmal pro Takt. Um es stattdessen in zwei zu fühlen, stellen Sie im Tempo-Fenster den Notenwert auf punktierte Viertelnote und geben ein Tempo wie 80 ein: zwei Klicks pro Takt.",
            "Exemple : avec une subdivision de 1, le 6/8 fait six clics par mesure. Pour le sentir à deux temps, réglez la valeur de note sur noire pointée dans le panneau Tempo et saisissez un tempo comme 80 : deux clics par mesure.",
            "Ejemplo: con una subdivisión de 1, el 6/8 hace clic seis veces por compás. Para sentirlo en dos, ponga la figura en negra con puntillo en el panel Tempo y escriba un tempo como 80: dos clics por compás.");
        Add("HelpFeelTitle", "Subdivision and swing", "Onderverdeling en swing", "Unterteilung und Swing", "Subdivision et swing", "Subdivisión y swing");
        Add("HelpFeel",
            "Subdivision splits every beat into smaller clicks: 3 gives three clicks in each beat. Swing delays the second click of each pair: 0.5 is even, and about 0.67 gives the long-short feel of swing. Swing needs an even subdivision, such as 2 or 4. Both are under {0}, in {1}.",
            "Onderverdeling splitst elke tel in kleinere tikken: 3 geeft drie tikken per tel. Swing vertraagt de tweede tik van elk paar: 0,5 is gelijkmatig en ongeveer 0,67 geeft het lang-kort van swing. Swing werkt alleen met een onderverdeling in een even aantal, zoals 2 of 4. Beide staan onder {0}, bij {1}.",
            "Die Unterteilung teilt jede Zählzeit in kleinere Klicks: 3 ergibt drei Klicks pro Zählzeit. Swing verzögert den zweiten Klick jedes Paars: 0,5 ist gleichmäßig, etwa 0,67 ergibt das Lang-kurz des Swings. Swing funktioniert nur mit einer geraden Unterteilung, etwa 2 oder 4. Beides finden Sie unter {0} im Bereich {1}.",
            "La subdivision découpe chaque temps en clics plus petits : 3 donne trois clics par temps. Le swing retarde le deuxième clic de chaque paire : 0,5 est régulier, et environ 0,67 donne le long-court du swing. Le swing ne marche qu’avec une subdivision paire, comme 2 ou 4. Les deux se trouvent sous {0}, dans {1}.",
            "La subdivisión parte cada pulso en clics más pequeños: 3 da tres clics por pulso. El swing retrasa el segundo clic de cada pareja: 0,5 es regular y alrededor de 0,67 da el largo-corto del swing. El swing solo funciona con una subdivisión par, como 2 o 4. Ambos están en {0}, en {1}.");
        Add("HelpFeelExample",
            "Example: in 4/4 with quarter notes as the note value, Subdivision 2 with Swing 0.67 swings the eighth notes.",
            "Voorbeeld: in 4/4 met kwartnoten als nootwaarde laat Onderverdeling 2 met Swing 0,67 de achtste noten swingen.",
            "Beispiel: Im 4/4-Takt mit Viertelnoten als Notenwert lässt Unterteilung 2 mit Swing 0,67 die Achtelnoten swingen.",
            "Exemple : en 4/4 avec des noires comme valeur de note, une subdivision de 2 avec un swing de 0,67 fait swinguer les croches.",
            "Ejemplo: en 4/4 con negras como figura, una subdivisión de 2 con un swing de 0,67 da swing a las corcheas.");
        Add("HelpStrength",
            "{0}, {1}, {2} and {3} set how loud a click is. Tap a beat to change it. A click set to {3} makes no sound but keeps its place in the count. Clicks between beats start as {2}.",
            "{0}, {1}, {2} en {3} bepalen hoe luid een tik klinkt. Tik op een tel om dat te wijzigen. Staat een tik op {3}, dan klinkt hij niet, maar hij behoudt zijn plaats in het tellen. Tikken tussen de tellen beginnen als {2}.",
            "{0}, {1}, {2} und {3} legen fest, wie laut ein Klick ist. Tippen Sie auf eine Zählzeit, um sie zu ändern. Steht ein Klick auf {3}, bleibt er lautlos, behält aber seinen Platz im Zählen. Klicks zwischen den Zählzeiten sind anfangs {2}.",
            "{0}, {1}, {2} et {3} règlent le volume d’un clic. Touchez un temps pour le changer. Un clic réglé sur {3} ne fait aucun bruit, mais garde sa place dans le compte. Les clics entre les temps sont d’abord {2}.",
            "{0}, {1}, {2} y {3} fijan lo fuerte que suena un clic. Toque un pulso para cambiarlo. Un clic en {3} no suena, pero conserva su lugar en la cuenta. Los clics entre pulsos empiezan en {2}.");
        Add("HelpStrengthExample",
            "Example: make beat 3 of 4/4 {0}, and keep the time yourself through it.",
            "Voorbeeld: zet tel 3 van 4/4 op {0} en houd zelf de maat vast.",
            "Beispiel: Stellen Sie Zählzeit 3 im 4/4-Takt auf {0} und halten Sie den Takt dort selbst.",
            "Exemple : réglez le temps 3 du 4/4 sur {0} et tenez le temps vous-même.",
            "Ejemplo: ponga el pulso 3 de un 4/4 en {0} y mantenga usted mismo el tiempo.");
    }
